effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
bool u_xlatb0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat6;
int u_xlati6;
bool u_xlatb6;
bool u_xlatb8;
float u_xlat9;
float u_xlat12;
bvec2 u_xlatb12;
float u_xlat13;
bool u_xlatb13;
vec2 u_xlat14;
float u_xlat15;
float u_xlat19;
bool u_xlatb19;
void main()
{
    u_xlat0.xy = acScreenNorm.yx * vec2(2.0, 2.0) + vec2(-1.0, -1.0);
    u_xlatb12.xy = equal(ivec4(int(_keep_aspect), int(_blend_mode), int(_keep_aspect), int(_blend_mode)), ivec4(1, 1, 1, 1)).xy;
    u_xlat1.xy = u_xlat0.xy * vec2(_viewport_ratio.y, _viewport_ratio.x);
    u_xlat0.xy = (u_xlatb12.x) ? u_xlat1.xy : u_xlat0.xy;
    u_xlat12 = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat12 = sqrt(u_xlat12);
    u_xlat1.x = _cur_time * _speed;
    u_xlat1.x = u_xlat1.x * 10.0;
    u_xlat1.x = floor(u_xlat1.x);
    u_xlat1.x = u_xlat1.x * 0.100000001;
    u_xlat1.x = _noise * u_xlat12 + u_xlat1.x;
    u_xlat13 = min(abs(u_xlat0.y), abs(u_xlat0.x));
    u_xlat19 = max(abs(u_xlat0.y), abs(u_xlat0.x));
    u_xlat19 = float(1.0) / u_xlat19;
    u_xlat13 = u_xlat19 * u_xlat13;
    u_xlat19 = u_xlat13 * u_xlat13;
    u_xlat2.x = u_xlat19 * 0.0208350997 + -0.0851330012;
    u_xlat2.x = u_xlat19 * u_xlat2.x + 0.180141002;
    u_xlat2.x = u_xlat19 * u_xlat2.x + -0.330299497;
    u_xlat19 = u_xlat19 * u_xlat2.x + 0.999866009;
    u_xlat2.x = u_xlat19 * u_xlat13;
    u_xlatb8 = abs(u_xlat0.y)<abs(u_xlat0.x);
    u_xlat2.x = u_xlat2.x * -2.0 + 1.57079637;
    u_xlat2.x = u_xlatb8 ? u_xlat2.x : float(0.0);
    u_xlat13 = u_xlat13 * u_xlat19 + u_xlat2.x;
    u_xlatb19 = u_xlat0.y<(-u_xlat0.y);
    u_xlat19 = u_xlatb19 ? -3.14159274 : float(0.0);
    u_xlat13 = u_xlat19 + u_xlat13;
    u_xlat19 = min(u_xlat0.y, u_xlat0.x);
    u_xlat0.x = max(u_xlat0.y, u_xlat0.x);
    u_xlatb6 = u_xlat19<(-u_xlat19);
    u_xlatb0 = u_xlat0.x>=(-u_xlat0.x);
    u_xlatb0 = u_xlatb0 && u_xlatb6;
    u_xlat0.x = (u_xlatb0) ? (-u_xlat13) : u_xlat13;
    u_xlat1.y = u_xlat0.x * _amount;
    u_xlat0.x = float(0.0);
    for(int u_xlati_loop_1 = int(1) ; u_xlati_loop_1<7 ; u_xlati_loop_1++)
    {
        u_xlat13 = float(u_xlati_loop_1);
        u_xlat2.xy = vec2(u_xlat13) + u_xlat1.xy;
        u_xlat13 = exp2(u_xlat13);
        u_xlat19 = u_xlat13 + u_xlat13;
        u_xlat14.xy = vec2(u_xlat19) * u_xlat2.xy;
        u_xlat3.xy = floor(u_xlat14.xy);
        u_xlat3.xy = u_xlat3.xy / vec2(u_xlat19);
        u_xlat3.x = dot(u_xlat3.xy, vec2(89.4400024, 19.3600006));
        u_xlat3.x = sin(u_xlat3.x);
        u_xlat3.x = u_xlat3.x * 22189.2207;
        u_xlat4 = u_xlat2.xyxy * vec4(u_xlat19) + vec4(0.0, 1.0, 1.0, 0.0);
        u_xlat4 = floor(u_xlat4);
        u_xlat4 = u_xlat4 / vec4(u_xlat19);
        u_xlat9 = dot(u_xlat4.xy, vec2(89.4400024, 19.3600006));
        u_xlat9 = sin(u_xlat9);
        u_xlat3.y = u_xlat9 * 22189.2207;
        u_xlat15 = dot(u_xlat4.zw, vec2(89.4400024, 19.3600006));
        u_xlat15 = sin(u_xlat15);
        u_xlat3.z = u_xlat15 * 22189.2207;
        u_xlat3.xyz = fract(u_xlat3.xyz);
        u_xlat2.xy = u_xlat2.xy * vec2(u_xlat19) + vec2(1.0, 1.0);
        u_xlat2.xy = floor(u_xlat2.xy);
        u_xlat2.xy = u_xlat2.xy / vec2(u_xlat19);
        u_xlat19 = dot(u_xlat2.xy, vec2(89.4400024, 19.3600006));
        u_xlat19 = sin(u_xlat19);
        u_xlat19 = u_xlat19 * 22189.2207;
        u_xlat19 = fract(u_xlat19);
        u_xlatb2.xy = greaterThanEqual(u_xlat14.xyxx, (-u_xlat14.xyxx)).xy;
        u_xlat14.xy = fract(abs(u_xlat14.xy));
        u_xlat2.x = (u_xlatb2.x) ? u_xlat14.x : (-u_xlat14.x);
        u_xlat2.y = (u_xlatb2.y) ? u_xlat14.y : (-u_xlat14.y);
        u_xlat2.xy = max(u_xlat2.xy, vec2(0.0, 0.0));
        u_xlat14.xy = u_xlat2.xy * vec2(-2.0, -2.0) + vec2(3.0, 3.0);
        u_xlat2.xy = u_xlat2.xy * u_xlat2.xy;
        u_xlat2.xy = u_xlat2.xy * u_xlat14.xy;
        u_xlat14.x = (-u_xlat3.x) + u_xlat3.y;
        u_xlat14.x = u_xlat2.y * u_xlat14.x + u_xlat3.x;
        u_xlat19 = (-u_xlat3.z) + u_xlat19;
        u_xlat19 = u_xlat2.y * u_xlat19 + u_xlat3.z;
        u_xlat19 = (-u_xlat14.x) + u_xlat19;
        u_xlat19 = u_xlat2.x * u_xlat19 + u_xlat14.x;
        u_xlat13 = u_xlat19 / u_xlat13;
        u_xlat0.x = u_xlat0.x + u_xlat13;
    }
    u_xlat6 = u_xlat12 + (-_radius);
    u_xlat0.x = u_xlat0.x + -0.5;
    u_xlat0.x = (-_length) * u_xlat0.x + u_xlat6;
    u_xlat6 = _smoothing + _smoothing;
    u_xlat0.x = u_xlat0.x + _smoothing;
    u_xlat6 = float(1.0) / u_xlat6;
    u_xlat0.x = u_xlat6 * u_xlat0.x;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat6 = u_xlat0.x * -2.0 + 3.0;
    u_xlat0.x = u_xlat0.x * u_xlat0.x;
    u_xlat1.w = u_xlat0.x * u_xlat6;
    u_xlat1.xyz = u_xlat1.www * _color.xyz;
    u_xlat2 = texture(inputImg, acScreenNorm.xy);
    u_xlat3 = u_xlat1 * u_xlat2;
    u_xlat4.xyz = u_xlat1.www * _color.xyz + u_xlat2.xyz;
    u_xlat4.w = u_xlat2.w;
    u_xlat0 = (u_xlatb12.y) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat1.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat0 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat2 = u_xlat2 * u_xlat5;
        u_xlat2 = u_xlat3 * u_xlat4 + u_xlat2;
        u_xlat1.x = u_xlat4.x * u_xlat2.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1.x : u_xlat2.w;
        fragColor.xyz = u_xlat2.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
